from __future__ import absolute_import

from selenium.common.exceptions import TimeoutException
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v22r3


class BtsBasicInfo(v22r3.BtsBasicInfo):
    _NON_DEFAULT_ICON = '//rad-parameter-non-default//span'

    def __init__(self, driver):
        super(BtsBasicInfo, self).__init__(driver)

    def check_rad_parameter_non_default(self, timeout=60):
        try:
            self.wait_for_visibility((By.XPATH, self._NON_DEFAULT_ICON), timeout)
            return True
        except TimeoutException:
            return False
